#include "Introspection.h"

#include "HydraGlobalState.h"
// generated by anari_generate_queries (SDK KHR JSONs + introspection/)
#include "anari_library_hydra_queries.h"
// std
#include <cstring>
#include <string>

namespace anari_hydra {

// Position of a generated-table extension name (no ANARI_ prefix) in the
// device's advertised list, or -1 when it is not advertised.
static int extensionIndex(
    const std::vector<const char *> &extensions, const char *extension)
{
  if (!extension)
    return -1;
  const std::string full = std::string("ANARI_") + extension;
  for (size_t i = 0; i < extensions.size() && extensions[i]; ++i)
    if (full == extensions[i])
      return int(i);
  return -1;
}

const ANARIParameter *reflectedParameterList(HydraGlobalState &state,
    const std::vector<const char *> &extensions,
    ANARIDataType type,
    const char *subtype)
{
  const auto key = std::make_pair(type, std::string(subtype ? subtype : ""));
  auto it = state.reflectedParamLists.find(key);
  if (it == state.reflectedParamLists.end()) {
    const auto *all = static_cast<const ANARIParameter *>(
        query_object_info(type, subtype, "parameter", ANARI_PARAMETER_LIST));
    if (!all)
      return nullptr;
    std::vector<ANARIParameter> kept;
    for (; all->name; ++all) {
      // Extension-existence gate: core and bridge entries carry no source
      // extension and always pass; KHR entries follow the delegate's claim.
      const char *ext = static_cast<const char *>(query_param_info(type,
          subtype,
          all->name,
          all->type,
          "sourceExtension",
          ANARI_STRING));
      if (!ext || extensionIndex(extensions, ext) >= 0)
        kept.push_back(*all);
    }
    kept.push_back(ANARIParameter{nullptr, ANARI_UNKNOWN});
    it = state.reflectedParamLists.emplace(key, std::move(kept)).first;
  }
  return it->second.data();
}

bool reflectsParameter(
    const ANARIParameter *list, const char *name, ANARIDataType parameterType)
{
  if (!list || !name)
    return false;
  for (; list->name; ++list)
    if (list->type == parameterType && std::strcmp(list->name, name) == 0)
      return true;
  return false;
}

const char **reflectedFrameChannels(
    HydraGlobalState &state, const std::vector<const char *> &extensions)
{
  auto &view = state.frameChannelView;
  if (view.empty()) {
    const ANARIParameter *frame =
        reflectedParameterList(state, extensions, ANARI_FRAME, nullptr);
    const auto *all = static_cast<const char *const *>(
        query_object_info(ANARI_FRAME, nullptr, "channel", ANARI_STRING_LIST));
    for (; all && *all; ++all)
      if (reflectsParameter(frame, *all, ANARI_DATA_TYPE))
        view.push_back(*all);
    view.push_back(nullptr);
  }
  return view.data();
}

const int32_t *sourceExtensionIndex(HydraGlobalState &state,
    const std::vector<const char *> &extensions,
    const char *extensionName)
{
  const int i = extensionIndex(extensions, extensionName);
  if (i < 0)
    return nullptr;
  // One stable int per extension slot so returned pointers outlive the call.
  const size_t n = extensions.size();
  if (state.extensionIndices.size() < n) {
    state.extensionIndices.resize(n);
    for (size_t k = 0; k < n; ++k)
      state.extensionIndices[k] = int32_t(k);
  }
  return &state.extensionIndices[size_t(i)];
}

} // namespace anari_hydra
